"use client";

import React, { useState } from "react";
import * as LucideIcons from "lucide-react";
import { Button } from "../../../components/ui/Button";
import { Input } from "../../../components/ui/Input";
import { useBarber, Service } from "@/context/BarberContext";

// Safe icon renderer
function Icon({ name, className }: { name: string, className?: string }) {
    const LucideIcon = (LucideIcons as any)[name];
    if (!LucideIcon) return <div className={className} style={{ width: '20px', height: '20px', backgroundColor: '#333', borderRadius: '4px' }} />;
    return <LucideIcon className={className} />;
}

export default function AdminServicos() {
    const { services, addService, updateService, removeService } = useBarber();

    const [isEditing, setIsEditing] = useState(false);
    const [editId, setEditId] = useState<string | null>(null);
    const [newName, setNewName] = useState("");
    const [newDescription, setNewDescription] = useState("");
    const [newPrice, setNewPrice] = useState("");
    const [newTime, setNewTime] = useState("");

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!newName || !newPrice) return;

        const priceNum = parseFloat(newPrice.replace("R$", "").replace(",", ".").trim());

        if (isEditing && editId !== null) {
            updateService(editId, {
                name: newName,
                description: newDescription,
                price: priceNum,
                duration: newTime.endsWith("min") ? newTime : `${newTime} min`
            });
            setIsEditing(false);
            setEditId(null);
        } else {
            addService({
                name: newName,
                description: newDescription,
                price: priceNum,
                duration: `${newTime} min`,
                icon: "✂️",
                active: true
            });
        }
        setNewName(""); setNewDescription(""); setNewPrice(""); setNewTime("");
    };

    const handleEdit = (service: Service) => {
        setIsEditing(true);
        setEditId(service.id);
        setNewName(service.name);
        setNewDescription(service.description || "");
        setNewPrice(service.price.toString());
        setNewTime(service.duration.replace(" min", ""));
    };

    const toggleServiceStatus = (service: Service) => {
        updateService(service.id, { active: !service.active });
    };

    const handleDelete = (id: string) => {
        if (confirm("Deseja realmente remover este serviço?")) {
            removeService(id);
        }
    };

    const cancelEdit = () => {
        setIsEditing(false);
        setEditId(null);
        setNewName(""); setNewDescription(""); setNewPrice(""); setNewTime("");
    };

    return (
        <div className="min-h-screen bg-[#0a0a0a] text-white p-6 lg:p-12 font-sans selection:bg-[#D4AF37] selection:text-black animate-fade-in-up">
            <div className="max-w-3xl mx-auto bg-[#111111] border border-[#1f1f1f] rounded-[40px] p-10 shadow-2xl h-[calc(100vh-100px)] flex flex-col relative overflow-hidden">
                <div className="absolute top-0 right-0 w-40 h-40 bg-[#D4AF37]/5 rounded-bl-[100px] pointer-events-none" />

                <header className="flex justify-between items-center mb-10">
                    <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-[#D4AF37]/10 rounded-2xl flex items-center justify-center text-[#D4AF37] border border-[#D4AF37]/20">
                            <Icon name="Scissors" className="w-6 h-6" />
                        </div>
                        <h2 className="text-3xl font-black tracking-tighter">
                            {isEditing ? "Editar Serviço" : "Gestão de Serviços"}
                        </h2>
                    </div>
                    {isEditing && (
                        <button onClick={cancelEdit} className="text-[10px] font-black uppercase text-red-500 hover:scale-105 transition-transform">Cancelar Edição</button>
                    )}
                </header>

                <form onSubmit={handleSubmit} className="space-y-6 mb-12">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase text-gray-500 tracking-widest ml-2">Nome do Serviço</label>
                            <Input value={newName} onChange={(e) => setNewName(e.target.value)} placeholder="Ex: Corte Degradê" className="bg-[#1a1a1a] border-[#2a2a2a] h-14 rounded-2xl" />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase text-gray-500 tracking-widest ml-2">Preço (R$)</label>
                                <div className="relative">
                                    <Icon name="DollarSign" className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
                                    <Input value={newPrice} onChange={(e) => setNewPrice(e.target.value)} placeholder="45.00" className="pl-12 bg-[#1a1a1a] border-[#2a2a2a] h-14 rounded-2xl" />
                                </div>
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase text-gray-500 tracking-widest ml-2">Duração (min)</label>
                                <div className="relative">
                                    <Icon name="Clock" className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
                                    <Input value={newTime} onChange={(e) => setNewTime(e.target.value)} placeholder="40" className="pl-12 bg-[#1a1a1a] border-[#2a2a2a] h-14 rounded-2xl" />
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase text-gray-500 tracking-widest ml-2">Descrição Curta</label>
                        <Input value={newDescription} onChange={(e) => setNewDescription(e.target.value)} placeholder="Descreva brevemente o serviço para o cliente..." className="bg-[#1a1a1a] border-[#2a2a2a] h-14 rounded-2xl" />
                    </div>

                    <Button type="submit" className={`w-full h-16 font-black uppercase tracking-[0.3em] transition-all rounded-3xl text-sm ${isEditing ? 'bg-emerald-600 hover:bg-emerald-700 shadow-xl shadow-emerald-500/20' : 'bg-[#D4AF37] text-black hover:bg-white shadow-xl shadow-[#D4AF37]/20'}`}>
                        {isEditing ? "Salvar Alterações" : "Cadastrar Novo Serviço"}
                    </Button>
                </form>

                <div className="flex-1 overflow-y-auto pr-4 space-y-4 custom-scrollbar">
                    {services.length > 0 ? services.map((service) => (
                        <div key={service.id} className={`bg-[#1a1a1a] border p-6 rounded-[2.5rem] flex items-center justify-between group transition-all ${editId === service.id ? 'border-[#D4AF37] bg-[#D4AF37]/5' : 'border-[#222] hover:border-[#D4AF37]/20'} ${!service.active ? 'opacity-50 grayscale' : ''}`}>
                            <div className="flex items-center gap-6">
                                <div className={`w-14 h-14 rounded-2xl bg-black border border-white/5 flex items-center justify-center text-2xl ${!service.active ? 'opacity-30' : ''}`}>
                                    {service.icon || "✂️"}
                                </div>
                                <div>
                                    <div className="flex items-center gap-3">
                                        <h4 className="font-bold text-gray-100">{service.name}</h4>
                                        <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-full ${service.active ? 'bg-emerald-500/10 text-emerald-500' : 'bg-red-500/10 text-red-500'}`}>
                                            {service.active ? "Ativo" : "Inativo"}
                                        </span>
                                    </div>
                                    <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest mt-1">
                                        R$ {service.price.toFixed(2)} • {service.duration}
                                    </p>
                                    {service.description && (
                                        <p className="text-[10px] text-gray-600 italic mt-2 line-clamp-1">{service.description}</p>
                                    )}
                                </div>
                            </div>
                            <div className="flex items-center gap-3">
                                <button
                                    onClick={() => toggleServiceStatus(service)}
                                    className={`w-11 h-11 rounded-2xl flex items-center justify-center transition-all border ${service.active ? 'bg-red-500/10 text-red-500 border-red-500/10 hover:bg-red-500 hover:text-white' : 'bg-emerald-500/10 text-emerald-500 border-emerald-500/10 hover:bg-emerald-500 hover:text-white'}`}
                                    title={service.active ? "Desativar" : "Ativar"}
                                >
                                    <Icon name={service.active ? "Power" : "Play"} className="w-5 h-5" />
                                </button>
                                <button
                                    onClick={() => handleEdit(service)}
                                    className="w-11 h-11 rounded-2xl bg-[#D4AF37]/10 text-[#D4AF37] border border-[#D4AF37]/10 flex items-center justify-center hover:bg-[#D4AF37] hover:text-black transition-all"
                                    title="Editar"
                                >
                                    <Icon name="Edit3" className="w-5 h-5" />
                                </button>
                                <button
                                    onClick={() => handleDelete(service.id)}
                                    className="w-11 h-11 rounded-2xl bg-white/5 text-gray-500 border border-white/5 flex items-center justify-center hover:bg-red-500 hover:text-white transition-all"
                                    title="Remover"
                                >
                                    <Icon name="Trash2" className="w-5 h-5" />
                                </button>
                            </div>
                        </div>
                    )) : (
                        <div className="py-20 text-center space-y-4">
                            <Icon name="Inbox" className="w-12 h-12 text-gray-700 mx-auto" />
                            <p className="text-gray-600 italic text-sm">Nenhum serviço disponível no momento.</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}
